cat > tests/task-order.test.ts <<'EOF'
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { after, before, describe, it } from "node:test";
import vm from "node:vm";
import { openDatabase, type Database } from "../src/db.ts";
import { listTasks } from "../src/tasks.ts";
import { newDbPath, ROOT, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
}

async function createTask(server: Running, title: string): Promise<void> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
}

async function fetchTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  return ((await response.json()) as { tasks: Task[] }).tasks;
}

function insert(db: Database, title: string, createdAt: string): void {
  db.all(
    "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
    title,
    createdAt,
    createdAt,
  );
}

describe("SL-008 list open tasks newest first, with an empty state", () => {
  describe("AC-1: tasks added as A, B, C", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: GET /api/tasks lists C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        await createTask(server, title);
        await new Promise((resolve) => setTimeout(resolve, 5));
      }
      assert.deepEqual(
        (await fetchTasks(server)).map((task) => task.title),
        ["C", "B", "A"],
      );
    });
  });

  describe("AC-1: ordering is by creation time", () => {
    it("AC-1: a task with an earlier created_at is listed after a later one, whatever its id", () => {
      const db = openDatabase(newDbPath());
      insert(db, "later", "2026-01-02T00:00:00.000Z");
      insert(db, "earlier", "2026-01-01T00:00:00.000Z");
      insert(db, "latest", "2026-01-03T00:00:00.000Z");
      assert.deepEqual(
        listTasks(db).map((task) => task.title),
        ["latest", "later", "earlier"],
      );
    });
  });

  describe("AC-2: tasks created at the same instant", () => {
    it("AC-2: the one saved last is listed first, every time", () => {
      const db = openDatabase(newDbPath());
      const instant = "2026-01-01T00:00:00.000Z";
      const titles = Array.from({ length: 30 }, (_, i) => `task ${i}`);
      titles.forEach((title) => insert(db, title, instant));

      const expected = [...titles].reverse();
      for (let run = 0; run < 5; run++) {
        assert.deepEqual(
          listTasks(db).map((task) => task.title),
          expected,
        );
      }
    });

    it("AC-2: tasks posted back to back come out in reverse order of posting", async () => {
      const server = await startServer();
      try {
        const titles = Array.from({ length: 40 }, (_, i) => `rapid ${i}`);
        for (const title of titles) await createTask(server, title);
        assert.deepEqual(
          (await fetchTasks(server)).map((task) => task.title),
          [...titles].reverse(),
        );
      } finally {
        await server.stop();
      }
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: GET /api/tasks answers 200 with an empty list", async () => {
      assert.deepEqual(await fetchTasks(server), []);
    });

    it("AC-3: the page has an empty-state element, hidden until the script decides", async () => {
      const html = await (await fetch(`${server.baseUrl}/`)).text();
      assert.match(html, /<[a-z]+(?=[^>]*id=["']empty-state["'])[^>]*>/);
      assert.match(html, /<[a-z]+(?=[^>]*id=["']empty-state["'])(?=[^>]*\bhidden\b)[^>]*>/);
    });

    for (const [label, tasks, hidden] of [
      ["no tasks", [], false],
      ["some tasks", [{ title: "A" }, { title: "B" }], true],
    ] as const) {
      it(`AC-3: the page script ${hidden ? "hides" : "shows"} the empty state with ${label}`, async () => {
        const script = readFileSync(join(ROOT, "public", "app.js"), "utf8");
        const element = () => ({
          hidden: undefined as boolean | undefined,
          children: [] as unknown[],
          addEventListener() {},
          replaceChildren(...nodes: unknown[]) {
            this.children = nodes;
          },
        });
        const elements: Record<string, ReturnType<typeof element>> = {
          "task-form": element(),
          "task-title": element(),
          "task-list": element(),
          "empty-state": element(),
        };
        const context = vm.createContext({
          document: {
            getElementById: (id: string) => elements[id],
            createElement: () => ({ textContent: "" }),
          },
          fetch: async () => ({ json: async () => ({ tasks }) }),
        });
        vm.runInContext(script, context);
        await new Promise((resolve) => setImmediate(resolve));

        assert.equal(elements["empty-state"].hidden, hidden);
        assert.equal(elements["task-list"].children.length, tasks.length);
      });
    }
  });

  describe("AC-4: about 1000 stored tasks", () => {
    let server: Running;
    before(async () => {
      const dbPath = newDbPath();
      const db = openDatabase(dbPath);
      db.all("BEGIN");
      for (let i = 0; i < 1000; i++) {
        insert(
          db,
          `Typical task number ${i}: remember to follow up on the thing`,
          new Date(Date.UTC(2026, 0, 1) + i * 1000).toISOString(),
        );
      }
      db.all("COMMIT");
      server = await startServer(dbPath);
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-4: 20 sequential GET /api/tasks have p95 under 100 ms and a body under 400000 bytes", async () => {
      const durations: number[] = [];
      for (let i = 0; i < 20; i++) {
        const start = performance.now();
        const response = await fetch(`${server.baseUrl}/api/tasks`);
        const body = await response.arrayBuffer();
        durations.push(performance.now() - start);

        assert.equal(response.status, 200);
        assert.ok(body.byteLength < 400000, `body is ${body.byteLength} bytes`);
      }
      durations.sort((a, b) => a - b);
      const p95 = durations[Math.ceil(durations.length * 0.95) - 1];
      assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
    });

    it("AC-4: the 1000 tasks come back newest first", async () => {
      const tasks = await fetchTasks(server);
      assert.equal(tasks.length, 1000);
      assert.equal(tasks[0].title, "Typical task number 999: remember to follow up on the thing");
    });
  });
});
